/bin/bash -lc "python - <<'PY'
import json, os, urllib.request
base=os.environ['GALAXY_URL'].rstrip('/')
hist='bbd44e69cb8906b5fb53ae8ae4557baa'
with open(os.environ['GALAXY_API_KEY_FILE']) as f:
    key=f.read().strip()
req=urllib.request.Request(base+f'/api/tools/upload1/build?history_id={hist}')
req.add_header('x-api-key', key)
with urllib.request.urlopen(req, timeout=30) as r:
    data=json.load(r)

def summarize(inp, prefix=''):
    if isinstance(inp, dict):
        name=inp.get('name') or ''
        typ=inp.get('type') or inp.get('model_class') or ''
        label=inp.get('label') or ''
        value=inp.get('value')
        opts=inp.get('options')
        line=prefix+f\"{name}\\t{typ}\\t{label}\"
        if value not in (None,'') and name in ('file_type','dbkey','file_count'):
            line += f\"\\tdefault={value}\"
        if opts and name in ('file_type','dbkey'):
            line += f\"\\toptions={len(opts)}\"
        print(line)
        for key in ('inputs','repeat','cases'):
            child=inp.get(key)
            if isinstance(child, list):
                if key=='cases':
                    for c in child:
                        print(prefix+f\"case value={c.get('value')} label={c.get('label','')}\")
                        for ci in c.get('inputs',[]): summarize(ci, prefix+'  ')
                else:
                    for ci in child: summarize(ci, prefix+'  ')
    elif isinstance(inp, list):
        for x in inp: summarize(x, prefix)
for inp in data['inputs']:
    summarize(inp)
PY"
